//! Exact whole REV source inputs: strict claims and independent native/artifact routes.
#[path="custom_final_next_wave_support.rs"]mod support;
use serde_json::Value;use std::collections::BTreeSet;
use ironsmith::{CardDefinition,GameState,ObjectId,PlayerId,Zone};
use ironsmith::decision::DecisionMaker;
const A:PlayerId=PlayerId(0);
fn fixture()->Value{serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/revolution-six-family-whole.json")).unwrap()}
fn cards<'a>(data:&'a Value,family:&str)->Vec<&'a Value>{data["mechanics"].as_array().unwrap().iter().filter(|r|r["keyword"].as_str()==Some(family)).flat_map(|r|r["representative_cards"].as_array().unwrap()).collect()}
fn collector(family:&str,expected:&[&str]){let data=fixture();let mut actual=BTreeSet::new();let mut failures=Vec::new();for card in cards(&data,family){let key=card["source_card_key"].as_str().unwrap();assert!(actual.insert(key),"duplicate {key}");assert_eq!(card["source_faces"].as_array().unwrap().len(),1,"whole face evidence {key}");assert_eq!(card["source_shape"],card["raw_source_record"]["shape"],"no layout flattening {key}");match support::linked_definitions(card){Ok(pair)=>assert_eq!(pair.len(),1,"{key}"),Err(error)=>failures.push(format!("{key}: {error}"))}}assert_eq!(actual,expected.iter().copied().collect(),"exact physical family scope {family}");assert!(failures.is_empty(),"{} {family} full source failures:\n{}",failures.len(),failures.join("\n"));}
fn named(family:&str,name:&str)->[CardDefinition;2]{let data=fixture();let card=cards(&data,family).into_iter().find(|c|c["name"].as_str()==Some(name)).unwrap_or_else(||panic!("missing {family} {name}"));support::definitions(card).unwrap()}
fn plain(name:&str,text:&str)->CardDefinition{ironsmith_compiler_runtime::compile_to_runtime_definition(name,text,false).unwrap()}
fn game()->GameState{let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.turn.active_player=A;game.turn.priority_player=Some(A);game.turn.phase=ironsmith::game_state::Phase::FirstMain;game.turn.step=None;game}
fn enter(game:&mut GameState,definition:&CardDefinition,dm:&mut impl ironsmith::decision::DecisionMaker)->ObjectId{let old=game.create_object_from_definition(definition,A,Zone::Hand);let stable=game.object(old).unwrap().stable_id;ironsmith::effects::execute_effect(game,&ironsmith::Effect::new(ironsmith::effects::MoveToZoneEffect::new(ironsmith::target::ChooseSpec::SpecificObject(old),Zone::Battlefield,false)),&mut ironsmith::effects::EffectContext::new(old,A,dm)).unwrap();game.find_object_by_stable_id(stable).unwrap()}
fn drain(game:&mut GameState,dm:&mut impl ironsmith::decision::DecisionMaker)->usize{let mut queue=ironsmith::triggers::TriggerQueue::new();ironsmith::game_loop::drain_pending_trigger_events_with_dm(game,&mut queue,dm).unwrap();ironsmith::game_loop::put_triggers_on_stack_with_dm(game,&mut queue,dm).unwrap();let n=game.stack.len();while !game.stack.is_empty(){ironsmith::game_loop::resolve_stack_entry_with(game,dm).unwrap();}n}
struct Choice(bool);impl ironsmith::decision::DecisionMaker for Choice{fn decide_targets(&mut self,game:&GameState,ctx:&ironsmith::decisions::context::TargetsContext)->Vec<ironsmith::game_state::Target>{ironsmith::decision::SelectFirstDecisionMaker.decide_targets(game,ctx)}fn decide_boolean(&mut self,_:&GameState,_:&ironsmith::decisions::context::BooleanContext)->bool{self.0}fn decide_objects(&mut self,game:&GameState,ctx:&ironsmith::decisions::context::SelectObjectsContext)->Vec<ObjectId>{ironsmith::decision::SelectFirstDecisionMaker.decide_objects(game,ctx)}}
#[test]fn actual_master_named_search_preserves_other_printed_abilities(){for route in 0..2{let mut game=game();let definition=named("Master","Arctic Drake")[route].clone();let desired=plain("Frost Breath","Type: Instant\nTap target creature.");let other=plain("Unrelated library card","Type: Instant\nYou gain 1 life.");game.create_object_from_definition(&desired,A,Zone::Library);game.create_object_from_definition(&other,A,Zone::Library);let mut dm=Choice(true);let source=enter(&mut game,&definition,&mut dm);assert_eq!(drain(&mut game,&mut dm),1);assert_eq!(game.player(A).unwrap().hand.len(),1);assert_eq!(game.object(game.player(A).unwrap().hand[0]).unwrap().name,"Frost Breath");assert!(game.current_has_static_ability_id(source,ironsmith_core::StaticAbilityId::Flying));}}
#[test]fn actual_propagate_three_counter_or_spawn_arms_are_exclusive(){for route in 0..2{for accepted in [false,true]{let mut game=game();let mut dm=Choice(accepted);let source=enter(&mut game,&named("Propagate","Meandering Titan")[route],&mut dm);assert_eq!(drain(&mut game,&mut dm),1);assert_eq!(game.counter_count(source,ironsmith::object::CounterType::PlusOnePlusOne),if accepted{3}else{0});let spawn:Vec<_>=game.battlefield.iter().filter_map(|id|game.object(*id)).filter(|object|object.subtypes.contains(&ironsmith::types::Subtype::Spawn)).collect();assert_eq!(spawn.len(),if accepted{0}else{3});for token in spawn{assert!(token.subtypes.contains(&ironsmith::types::Subtype::Eldrazi));assert_eq!(game.calculated_power(token.id),Some(0));assert_eq!(game.calculated_toughness(token.id),Some(1));}assert!(game.current_has_static_ability_id(source,ironsmith_core::StaticAbilityId::Trample));}}}

