#[test]fn actual_teach_uses_existing_keyword_at_resolution_not_counter_presence(){for route in 0..2{for already_flying in [false,true]{let mut game=game();let body=if already_flying{"Type: Creature\nPower/Toughness: 2/2\nFlying"}else{"Type: Creature\nPower/Toughness: 2/2"};let target=game.create_object_from_definition(&plain("Teach witness",body),A,Zone::Battlefield);let mut dm=Choice(true);enter(&mut game,&named("Teach","Civic Copterist")[route],&mut dm);assert_eq!(drain(&mut game,&mut dm),1);assert!(game.current_has_static_ability_id(target,ironsmith_core::StaticAbilityId::Flying));assert_eq!(game.counter_count(target,ironsmith::object::CounterType::PlusOnePlusOne),u32::from(already_flying));assert_eq!(game.counter_count(target,ironsmith::object::CounterType::Flying),u32::from(!already_flying));}}}

fn announce(game:&mut GameState,action:ironsmith::decision::LegalAction,dm:&mut impl ironsmith::decision::DecisionMaker)->ironsmith::triggers::TriggerQueue{use ironsmith::game_loop::*;let mut queue=ironsmith::triggers::TriggerQueue::new();let mut state=PriorityLoopState::new(2);let mut progress=apply_priority_response_with_dm(game,&mut queue,&mut state,&PriorityResponse::PriorityAction(action),dm).unwrap();for _ in 0..64{if !state.has_pending_action(){break}let ironsmith::GameProgress::NeedsDecisionCtx(ctx)=progress else{panic!("{progress:?}")};progress=apply_decision_context_with_dm(game,&mut queue,&mut state,&ctx,dm).unwrap();}assert!(!state.has_pending_action());queue}
#[test]fn actual_multitude_total_price_creates_one_permanent_copy_only_when_selected(){for route in 0..2{for alternative in [false,true]{let mut game=game();let definition=named("Multitude","Sylph of the Tugae")[route].clone();let source=game.create_object_from_definition(&definition,A,Zone::Hand);game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::White,1);game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Colorless,5);
 let action=ironsmith::decision::compute_legal_actions(&game,A).unwrap().into_iter().find(|action|matches!(action,ironsmith::decision::LegalAction::CastSpell{spell_id,casting_method,..}if *spell_id==source&&matches!(casting_method,ironsmith::alternative_cast::CastingMethod::Alternative(_))==alternative)).unwrap();let mut dm=Choice(true);let mut queue=announce(&mut game,action,&mut dm);assert_eq!(game.player(A).unwrap().mana_pool.total(),if alternative{0}else{3});ironsmith::game_loop::drain_pending_trigger_events_with_dm(&mut game,&mut queue,&mut dm).unwrap();ironsmith::game_loop::put_triggers_on_stack_with_dm(&mut game,&mut queue,&mut dm).unwrap();while !game.stack.is_empty(){ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();}
 let objects:Vec<_>=game.battlefield.iter().filter_map(|id|game.object(*id)).filter(|object|object.name=="Sylph of the Tugae").collect();assert_eq!(objects.len(),if alternative{2}else{1});assert_eq!(objects.iter().filter(|object|object.kind==ironsmith::object::ObjectKind::Token).count(),usize::from(alternative));for object in objects{assert!(game.current_has_static_ability_id(object.id,ironsmith_core::StaticAbilityId::Vigilance));assert_eq!(game.calculated_power(object.id),Some(3));assert_eq!(game.calculated_toughness(object.id),Some(2));}
}}}

fn activation(game:&GameState,source:ObjectId)->Option<ironsmith::decision::LegalAction>{ironsmith::decision::compute_legal_actions(game,A).unwrap().into_iter().find(|action|matches!(action,ironsmith::decision::LegalAction::ActivateAbility{source:id,..}if *id==source))}
#[test]fn actual_quarantine_excludes_cost_contributor_and_monolith_observes_one_paid_batch(){for route in 0..2{let mut game=game();let source=game.create_object_from_definition(&named("Traverse","Cloud Crossing")[route],A,Zone::Battlefield);let stable=game.object(source).unwrap().stable_id;game.create_object_from_definition(&named("Traverse","Elseworld Monolith")[route],A,Zone::Battlefield);let contributor=game.create_object_from_definition(&plain("Payment witness","Type: Creature\nPower/Toughness: 3/4"),A,Zone::Battlefield);game.create_object_from_definition(&plain("Opponent witness","Type: Creature\nPower/Toughness: 9/9"),PlayerId(1),Zone::Battlefield);let aura=game.create_object_from_definition(&named("Traverse","Quarantine")[route],A,Zone::Battlefield);assert!(game.attach_object_to_target(aura,ironsmith::object::AttachmentTarget::Object(contributor)));assert!(activation(&game,source).is_none(),"enchanted creature and opponent cannot pay");game.move_object_by_effect(aura,Zone::Hand).unwrap();let action=activation(&game,source).expect("restriction leaves with aura");let mut dm=Choice(true);let mut queue=announce(&mut game,action,&mut dm);assert!(game.is_tapped(contributor));ironsmith::game_loop::drain_pending_trigger_events_with_dm(&mut game,&mut queue,&mut dm).unwrap();ironsmith::game_loop::put_triggers_on_stack_with_dm(&mut game,&mut queue,&mut dm).unwrap();assert_eq!(game.stack.len(),2,"one activation plus one paid-batch observer, regardless contributor count");ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();assert_eq!(game.player(A).unwrap().life,22);assert_eq!(game.object(source).unwrap().zone,Zone::Battlefield,"payment observer precedes resolved designation/sacrifice");ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Graveyard);}}
#[test]fn actual_cartographers_exiles_exact_paid_rift_then_grants_only_its_additional_discard_price(){for route in 0..2{let mut game=game();let cartographers=game.create_object_from_definition(&named("Traverse","Rift Cartographers")[route],A,Zone::Battlefield);let definition=named("Traverse","Cloud Crossing")[route].clone();let source=game.create_object_from_definition(&definition,A,Zone::Battlefield);let stable=game.object(source).unwrap().stable_id;let unlinked=game.create_object_from_definition(&definition,A,Zone::Exile);game.create_object_from_definition(&plain("Additional contributor","Type: Creature\nPower/Toughness: 1/2"),A,Zone::Battlefield);let mut dm=Choice(true);let action=activation(&game,source).unwrap();let mut queue=announce(&mut game,action,&mut dm);ironsmith::game_loop::drain_pending_trigger_events_with_dm(&mut game,&mut queue,&mut dm).unwrap();ironsmith::game_loop::put_triggers_on_stack_with_dm(&mut game,&mut queue,&mut dm).unwrap();assert_eq!(game.stack.len(),2);ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();let exiled=game.find_object_by_stable_id(stable).unwrap();assert_eq!(game.object(exiled).unwrap().zone,Zone::Exile,"performer means Rift, not tapped contributor");assert_eq!(game.object(cartographers).unwrap().zone,Zone::Battlefield);ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Blue,1);game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Colorless,2);
 let castable=|game:&GameState,id:ObjectId|ironsmith::decision::compute_legal_actions(game,A).unwrap().iter().any(|a|matches!(a,ironsmith::decision::LegalAction::CastSpell{spell_id,..}if *spell_id==id));assert!(!castable(&game,exiled),"additional discard is mandatory");game.create_object_from_definition(&plain("Discard witness","Type: Instant\nYou gain 1 life."),A,Zone::Hand);assert!(castable(&game,exiled));assert!(!castable(&game,unlinked),"same printed definition is not the linked incarnation");game.move_object_by_effect(cartographers,Zone::Hand).unwrap();assert!(!castable(&game,exiled),"provider-scoped permission ends when its source leaves");}}

#[test]fn actual_anesthesiologist_gates_whole_teach_or_life_branch(){for route in 0..2{for white in [false,true]{let mut game=game();let definition=named("Teach","Anesthesiologist")[route].clone();let source=game.create_object_from_definition(&definition,A,Zone::Battlefield);if white{game.create_object_from_definition(&plain("White witness","Mana cost: {W}\nType: Artifact"),A,Zone::Battlefield);}let trigger=definition.abilities.iter().find_map(|ability|match &ability.kind{ironsmith::ability::AbilityKind::Triggered(trigger)=>Some(trigger),_=>None}).unwrap();let mut dm=Choice(true);let mut ctx=ironsmith::effects::EffectContext::new(source,A,&mut dm);for effect in trigger.effects.all_effects(){ironsmith::effects::execute_effect(&mut game,effect,&mut ctx).unwrap();}assert_eq!(game.current_has_static_ability_id(source,ironsmith_core::StaticAbilityId::Lifelink),white);assert_eq!(game.player(A).unwrap().life,if white{20}else{22});}}}

#[test]fn actual_adaptive_hydra_repeats_resolution_choice_and_rechecks_chosen_ability(){for route in 0..2{let mut game=game();let definition=named("Teach","Adaptive Hydra")[route].clone();let source=game.create_object_from_definition(&definition,A,Zone::Battlefield);let trigger=definition.abilities.iter().find_map(|ability|match &ability.kind{ironsmith::ability::AbilityKind::Triggered(trigger)=>Some(trigger),_=>None}).unwrap();let mut dm=ironsmith::decision::SelectFirstDecisionMaker;let mut ctx=ironsmith::effects::EffectContext::new(source,A,&mut dm).with_x(2);for effect in trigger.effects.all_effects(){ironsmith::effects::execute_effect(&mut game,effect,&mut ctx).unwrap();}assert_eq!(game.counter_count(source,ironsmith::object::CounterType::Haste),1);assert_eq!(game.counter_count(source,ironsmith::object::CounterType::PlusOnePlusOne),2,"initial teaching plus X repeats, each testing current ability");}}

struct HarnessChoice{pay:bool,resource:ObjectId,target:ObjectId}impl ironsmith::decision::DecisionMaker for HarnessChoice{fn decide_boolean(&mut self,_:&GameState,_:&ironsmith::decisions::context::BooleanContext)->bool{true}fn decide_options(&mut self,game:&GameState,ctx:&ironsmith::decisions::context::SelectOptionsContext)->Vec<usize>{if ctx.description.starts_with("Choose optional costs"){return ctx.options.iter().filter(|option|option.legal&&self.pay).map(|option|option.index).collect()}ironsmith::decision::SelectFirstDecisionMaker.decide_options(game,ctx)}fn decide_objects(&mut self,game:&GameState,ctx:&ironsmith::decisions::context::SelectObjectsContext)->Vec<ObjectId>{if ctx.candidates.iter().any(|candidate|candidate.id==self.resource&&candidate.legal){vec![self.resource]}else{ironsmith::decision::SelectFirstDecisionMaker.decide_objects(game,ctx)}}fn decide_targets(&mut self,_:&GameState,_:&ironsmith::decisions::context::TargetsContext)->Vec<ironsmith::game_state::Target>{vec![ironsmith::game_state::Target::Object(self.target)]}}
#[test]fn actual_harness_alias_pays_optional_tap_power_and_paid_resolution_rider(){for route in 0..2{for pay in [false,true]{let mut game=game();let definition=named("Harness","Confusion")[route].clone();let resource=game.create_object_from_definition(&plain("Payment creature","Type: Creature\nPower/Toughness: 2/3"),A,Zone::Battlefield);let target=game.create_object_from_definition(&plain("Bounce witness","Type: Artifact"),PlayerId(1),Zone::Battlefield);let stable=game.object(target).unwrap().stable_id;game.create_object_from_definition(&plain("Draw witness","Type: Instant\nYou gain 1 life."),A,Zone::Library);let source=game.create_object_from_definition(&definition,A,Zone::Hand);game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Blue,1);game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Colorless,2);let action=ironsmith::decision::compute_legal_actions(&game,A).unwrap().into_iter().find(|action|matches!(action,ironsmith::decision::LegalAction::CastSpell{spell_id,..}if *spell_id==source)).unwrap();let mut dm=HarnessChoice{pay,resource,target};let _queue=announce(&mut game,action,&mut dm);assert_eq!(game.is_tapped(resource),pay);assert_eq!(game.player(A).unwrap().mana_pool.total(),if pay{2}else{0});ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Hand);assert_eq!(game.player(A).unwrap().hand.len(),usize::from(pay),"paid label governs rider, not source keyword presence");}}}
